  // but is not present in the auth.ini file that we manage. There is nothing to
  // clean up locally.
  if (revokeResult === 'revoked' || revokeResult === 'unreachable') {
    context.globalWarn(`The auth token for ${registry} was not found in ${configPath}`)
    context.globalWarn('The token was revoked on the registry but must be removed manually')
    return `Logged out of ${registry}`
  }

  throw new PnpmError(
    'LOGOUT_FAILED',
    `Failed to log out of ${registry}. The token was not found in ${configPath} and may still need to be revoked on the registry`
