type RevokeResult = 'revoked' | 'failed' | 'unreachable'

async function revokeToken (context: LogoutContext, registry: string, token: string): Promise<RevokeResult> {
  const revokeUrl = `${registry}-/user/token/${encodeURIComponent(token)}`
